// Calculate historical averages from pricing history data
const items = $input.all();

// Get property details from the first item (passed from previous nodes)
const propertyDetails = items[0].json;

// Initialize counters
let totalPrice = 0;
let totalOccupancy = 0;
let count = 0;

// Sum all prices and occupancy rates
for (const item of items) {
  if (item.json.price !== undefined && item.json.price !== null) {
    totalPrice += parseFloat(item.json.price);
  }
  if (item.json.occupancy !== undefined && item.json.occupancy !== null) {
    totalOccupancy += parseFloat(item.json.occupancy);
  }
  count++;
}

// Calculate averages
const averagePrice = count > 0 ? totalPrice / count : 0;
const averageOccupancy = count > 0 ? totalOccupancy / count : 0;

// Return result with property details and calculated averages
return [{
  json: {
    ...propertyDetails,
    averagePrice: averagePrice,
    averageOccupancy: averageOccupancy,
    historicalDataPoints: count
  }
}];

// Compile all context data for AI pricing recommendations

// Get data from previous nodes
const propertyConfig = $('Get Property Configuration').first().json;
const historicalData = $('Calculate Historical Averages').first().json;
const eventbriteResponse = $('Get Eventbrite Events').first().json;
const weatherResponse = $('Get Weather Forecast').first().json;

// Compile property details
const propertyDetails = {
  name: propertyConfig.property_name || '',
  current_price: propertyConfig.current_price || 0,
  min_price: propertyConfig.min_price || 0,
  max_price: propertyConfig.max_price || 0,
  city: propertyConfig.city || '',
  state: propertyConfig.state || '',
  property_id: propertyConfig.property_id || ''
};

// Extract historical averages
const historicalAverages = {
  averagePrice: historicalData.averagePrice || 0,
  averageOccupancy: historicalData.averageOccupancy || 0
};

// Extract events from Eventbrite response
const events = eventbriteResponse.events || [];

// Extract weather forecast
const weatherForecast = weatherResponse.list || [];

// Get pricing decision contact
const pricing_decision_contact = propertyConfig.pricing_decision_contact || '';

// Compile everything into a single context object
const compiledContext = {
  property: propertyDetails,
  historical: historicalAverages,
  events: events,
  weather: weatherForecast,
  pricing_decision_contact: pricing_decision_contact,
  timestamp: new Date().toISOString()
};

// Return as single item
return [{ json: compiledContext }];

