// Parse OpenAI response and filter recommendations
const items = $input.all();
const filteredRecommendations = [];

for (const item of items) {
  try {
    // Extract the OpenAI response
    const response = item.json;

    // Parse the content from OpenAI response
    let content;
    if (response.choices && response.choices[0] && response.choices[0].message) {
      content = response.choices[0].message.content;
    } else if (typeof response === 'string') {
      content = response;
    } else {
      console.log('Unexpected response format:', response);
      continue;
    }

    // Parse JSON from content if it's a string
    let recommendations;
    if (typeof content === 'string') {
      // Try to extract JSON from markdown code blocks if present
      const jsonMatch = content.match(/```json\s*([\s\S]*?)\s*```/) || content.match(/```\s*([\s\S]*?)\s*```/);
      if (jsonMatch) {
        recommendations = JSON.parse(jsonMatch[1]);
      } else {
        recommendations = JSON.parse(content);
      }
    } else {
      recommendations = content;
    }

    // Ensure recommendations is an array
    if (!Array.isArray(recommendations)) {
      if (recommendations.recommendations) {
        recommendations = recommendations.recommendations;
      } else {
        console.log('Recommendations is not an array:', recommendations);
        continue;
      }
    }

    // Get property_id and contact from the original item
    const property_id = item.json.property_id || item.json.propertyId;
    const pricing_decision_contact = item.json.pricing_decision_contact || item.json.contact;
    const current_price = parseFloat(item.json.current_price || item.json.currentPrice || 0);

    // Filter and process each recommendation
    for (const rec of recommendations) {
      const recommended_price = parseFloat(rec.recommended_price || rec.recommendedPrice || 0);

      // Calculate percentage change
      let percentage_change = 0;
      if (current_price > 0) {
        percentage_change = ((recommended_price - current_price) / current_price) * 100;
      }

      // Filter: only keep if absolute percentage change is 15% or more
      if (Math.abs(percentage_change) >= 15) {
        filteredRecommendations.push({
          property_id: property_id,
          pricing_decision_contact: pricing_decision_contact,
          current_price: current_price,
          recommended_price: recommended_price,
          percentage_change: Math.round(percentage_change * 100) / 100, // Round to 2 decimals
          date: rec.date,
          reasoning: rec.reasoning || rec.reason || '',
          confidence: rec.confidence || 'medium'
        });
      }
    }
  } catch (error) {
    console.error('Error processing item:', error.message);
    console.error('Item data:', item.json);
  }
}

// Return filtered recommendations
return filteredRecommendations.map(rec => ({ json: rec }));

// Group all recommendations by pricing_decision_contact
const contactGroups = {};

// Process all input items
for (const item of $input.all()) {
  const contact = item.json.pricing_decision_contact;

  if (!contact) continue;

  if (!contactGroups[contact]) {
    contactGroups[contact] = {
      contact: contact,
      properties: [],
      recommendations: [],
      totalEstimatedRevenue: 0
    };
  }

  // Add property with its recommendations
  const propertyData = {
    propertyId: item.json.property_id,
    propertyName: item.json.property_name,
    currentPrice: item.json.current_price,
    recommendedPrice: item.json.recommended_price,
    percentageChange: item.json.percentage_change,
    estimatedRevenue: item.json.estimated_additional_revenue || 0,
    priority: item.json.priority || 'medium',
    reasoning: item.json.reasoning,
    dateRange: item.json.date_range
  };

  contactGroups[contact].properties.push(propertyData);
  contactGroups[contact].recommendations.push(propertyData);
  contactGroups[contact].totalEstimatedRevenue += propertyData.estimatedRevenue;
}

// Process each contact group
const results = [];

for (const contact in contactGroups) {
  const group = contactGroups[contact];

  // Sort recommendations by priority and percentage change
  const priorityOrder = { 'high': 3, 'medium': 2, 'low': 1 };

  group.recommendations.sort((a, b) => {
    const priorityDiff = (priorityOrder[b.priority] || 2) - (priorityOrder[a.priority] || 2);
    if (priorityDiff !== 0) return priorityDiff;
    return Math.abs(b.percentageChange) - Math.abs(a.percentageChange);
  });

  // Get top 5 recommendations
  const top5Recommendations = group.recommendations.slice(0, 5);

  results.push({
    json: {
      contact: group.contact,
      totalProperties: group.properties.length,
      totalRecommendations: group.recommendations.length,
      totalEstimatedRevenue: group.totalEstimatedRevenue,
      properties: group.properties,
      top5Recommendations: top5Recommendations,
      allRecommendations: group.recommendations
    }
  });
}

return results;

