// Parse callback data from Telegram or WhatsApp
const item = $input.item.json;

// Determine the source (Telegram or WhatsApp)
let action, recommendation_id, contact_id, contact_type;

if (item.callback_query) {
  // Telegram callback
  const callbackData = item.callback_query.data;
  const parts = callbackData.split('_');

  action = parts[0]; // mark_applied, skip, or view_report
  recommendation_id = parts[1];
  contact_id = item.callback_query.from.id.toString();
  contact_type = 'telegram';

} else if (item.message || item.interactive) {
  // WhatsApp callback
  let callbackData;

  if (item.interactive && item.interactive.button_reply) {
    callbackData = item.interactive.button_reply.id;
  } else if (item.message && item.message.text) {
    callbackData = item.message.text;
  }

  const parts = callbackData.split('_');
  action = parts[0];
  recommendation_id = parts[1];
  contact_id = item.from;
  contact_type = 'whatsapp';
}

// Return structured data
return {
  action: action,
  recommendation_id: recommendation_id,
  contact_id: contact_id,
  contact_type: contact_type,
  timestamp: new Date().toISOString(),
  raw_callback: item
};

